callable_validator.py<pre><code>from pydantic_jsonschema import JsonType


def normalize_phone(value: JsonType) -&gt; str:
    digits = "".join(character for character in str(value) if character.isdigit())

    if len(digits) != 10:
        msg = "Phone number must contain 10 digits"
        raise ValueError(msg)

    return f"({digits[:3]}) {digits[3:6]}-{digits[6:]}"


format_validators = {"phone": normalize_phone}
</code></pre>

annotated_validator.py<pre><code>from typing import Annotated

from pydantic import AfterValidator, Field


def round_price(value: float) -&gt; float:
    return round(value, 2)


PositivePrice = Annotated[
    float,
    Field(gt=0),
    AfterValidator(round_price),
]

format_validators = {"price": PositivePrice}
</code></pre>
